class Registry {
    private val listeners = mutableSetOf<WeakReference<Listener>>()

    fun add(listener: Listener) = listeners.add(WeakReference(listener))

    fun notifyAll(event: Event) {
        listeners.removeAll { it.get() == null }          // reap dead entries
        listeners.mapNotNull { it.get() }.forEach { it.onEvent(event) }
    }
}
